def bookingRackEvenKeyCensus(drawers):
    a=drawers
    out=[]
    end=float('-inf')
    for s,e in sorted(a,key=lambda r:(r[1],r[0])):
        if s>=end:
            out.append(e-s)
            end=e
    return sum(x%2==0 for x in out)

